TEMPLATE='''"use client";
import { useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
const lesson = __DATA__;
export default function Demo({slug}:{slug:string}) {
  const [step,setStep]=useState(0);
  return <Lesson slug={slug} predict={{question:lesson.question,options:lesson.options,answer:lesson.answer}} exploreHint={lesson.hint} minInteractions={2} reveal={()=><p>{lesson.explanation}</p>}>
    {({locked,interact})=><div><svg viewBox="0 0 340 190" className="stage-svg" role="img" aria-label={step === 0 ? "Diagram hidden until you explore." : step === 1 ? lesson.label : lesson.shownLabel}>
      {step === 0 && <text x="170" y="96" textAnchor="middle" fill="var(--muted)" fontSize="16">Evidence hidden</text>}
      {step >= 1 && <g>__SVG__</g>}
      {step >= 2 && <g>__EXTRA__</g>}
    </svg><Row><Control disabled={locked || step !== 0} onClick={()=>{setStep(1);interact();}}>Inspect the subject</Control><Control disabled={locked || step !== 1} onClick={()=>{setStep(2);interact();}}>Trace the evidence</Control></Row></div>}
  </Lesson>;
}
'''
for c in CASES:
    slug=c['slug'];out=Path('src/demos/life')/slug
    if out.exists():raise ValueError(f'Existing lesson: {slug}')
    out.mkdir(parents=True)
    lesson={k:c[k] for k in ('question','options','answer','hint','explanation','label')}
    lesson['shownLabel']=c['label']+' '+c['explanation']
    demo=TEMPLATE.replace('__DATA__',json.dumps(lesson,ensure_ascii=False,indent=2)).replace('__SVG__',c['svg']).replace('__EXTRA__',c['extra'])
    (out/'Demo.tsx').write_text(demo)
    meta={'slug':slug,'title':c['title'],'hook':c['hook'],'domain':'life','concept':slug,'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Animals have structures and activities that can be studied.'],'doesNotKnow':[c['explanation']]},'misconception':'The features shown in this question have only one possible interpretation.','objective':c['question'],'claims':[{'id':f'life.{slug}.c1','text':c['hook']+' '+c['question']+' '+c['explanation'],'support':'source','source':c['source'],'status':'unverified'},{'id':f'life.{slug}.c2','text':c['label'],'support':'convention','source':'Drawing convention and explicitly stated model inputs.','status':'unverified'},{'id':f'life.{slug}.c3','text':c['recallq']+' '+c['recallwhy'],'support':'source','source':c['source'],'status':'unverified'}],'confidence':'','recall':{'question':c['recallq'],'options':c['recallo'],'answer':0,'why':c['recallwhy']},'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':1}
    (out/'meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
print('Generated',len(CASES),'bird drafts')
